setup.command:
cat > pp.config.yaml << 'EOF'
default_action: allow
mode: observe
rules:
  - id: block-delete
    tool: delete_user_data
    action: block
  - id: hold-deploy
    tool: deploy_production
    action: require_approval
EOF
cat pp.config.yaml
cat > my-mcp-server.js << 'EOF'
const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout, terminal: false });
function send(obj) { process.stdout.write(JSON.stringify(obj) + '\n'); }
const TOOLS = [
  { name: 'safe_tool', description: 'A safe test tool', inputSchema: { type: 'object', properties: {} } },
  { name: 'delete_user_data', description: 'Dangerous delete tool', inputSchema: { type: 'object', properties: {} } },
  { name: 'deploy_production', description: 'Sensitive deploy tool', inputSchema: { type: 'object', properties: {} } }
];
rl.on('line', (line) => {
  if (!line.trim()) return;
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  const id = msg.id;
  const method = msg.method;
  if (msg.method === 'notifications/initialized' && id === undefined) return;
  if (method === 'initialize') {
    send({ jsonrpc: '2.0', id, result: { protocolVersion: '2025-11-25', capabilities: { tools: {} }, serverInfo: { name: 'test-server', version: '1.0.0' } } });
  } else if (method === 'tools/list') {
    send({ jsonrpc: '2.0', id, result: { tools: TOOLS } });
  } else if (method === 'tools/call') {
    const name = msg.params && msg.params.name;
    send({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: 'executed:' + name }] } });
  } else if (method === 'ping') {
    send({ jsonrpc: '2.0', id, result: {} });
  } else {
    send({ jsonrpc: '2.0', id, error: { code: -32601, message: 'Method not found' } });
  }
});
EOF
echo "--- files written ---" && ls -la

